          "id": "code-ml-17-1-ch17_1_scratch",
          "title": "First-Principles: Uji Sensitivitas Rotasi Ortogonal (Tree vs L2)",
          "language": "python",
          "filename": "17_1_orthogonal_rotation_bias.py",
          "code": "import numpy as np\n\ndef evaluate_rotation_sensitivity(seed: int = 42) -> dict:\n    \"\"\"Eksperimen Grinsztajn et al. (2022): menguji efek rotasi ortogonal fitur pada pohon vs jarak L2.\"\"\"\n    rng = np.random.default_rng(seed)\n    n, d = 400, 8\n    X = rng.normal(0, 1, size=(n, d))\n    # Target tabular murni bergantung pada aturan axis-aligned 2 fitur pertama (6 fitur sisanya noise)\n    y = ((X[:, 0] > 0.2) & (X[:, 1] < 0.5)).astype(int)\n\n    # Buat matriks rotasi ortogonal acak Q (Q^T Q = I) via QR decomposition\n    Q, _ = np.linalg.qr(rng.normal(0, 1, size=(d, d)))\n    X_rot = X @ Q\n\n    # 1. Jarak Euclidean (inductive bias MLP/kNN) 100% INVARIAN terhadap rotasi ortogonal\n    dist_orig = np.linalg.norm(X[0] - X[1])\n    dist_rot = np.linalg.norm(X_rot[0] - X_rot[1])\n\n    # 2. Best single axis-aligned decision stump accuracy (inductive bias Tree/GBDT)\n    def best_stump_acc(Xm, ym):\n        best = 0.0\n        for col in range(Xm.shape[1]):\n            qs = np.quantile(Xm[:, col], np.linspace(0.1, 0.9, 17))\n            for t in qs:\n                acc1 = np.mean((Xm[:, col] > t) == ym)\n                best = max(best, acc1, 1.0 - acc1)\n        return float(best)\n\n    return {\n        \"euclidean_dist_diff\": round(float(abs(dist_orig - dist_rot)), 12),\n        \"stump_acc_axis_aligned\": round(best_stump_acc(X, y), 4),\n        \"stump_acc_after_rotation\": round(best_stump_acc(X_rot, y), 4),\n    }\n\nres = evaluate_rotation_sensitivity()\nprint(f\"Perubahan Jarak L2 Pasca-Rotasi (MLP/kNN Invarian): {res['euclidean_dist_diff']:.12f}\")\nprint(f\"Akurasi Stump 1-Split (Fitur Asli Axis-Aligned)   : {res['stump_acc_axis_aligned']*100:.2f}%\")\nprint(f\"Akurasi Stump 1-Split (Fitur Dirotasi Ortogonal)  : {res['stump_acc_after_rotation']*100:.2f}%\")",
          "expectedOutput": "Perubahan Jarak L2 Pasca-Rotasi (MLP/kNN Invarian): 0.000000000000\nAkurasi Stump 1-Split (Fitur Asli Axis-Aligned)   : 86.25%\nAkurasi Stump 1-Split (Fitur Dirotasi Ortogonal)  : 78.25%",
