          "code": "import numpy as np\nfrom sklearn.ensemble import HistGradientBoostingClassifier\nfrom sklearn.metrics import roc_auc_score\nfrom sklearn.model_selection import train_test_split\nfrom sklearn.neural_network import MLPClassifier\nfrom sklearn.pipeline import Pipeline\nfrom sklearn.preprocessing import QuantileTransformer, StandardScaler\n\nrng = np.random.default_rng(42)\nn = 1200\n# 4 fitur informatif dengan skala heavy-tail + 20 fitur noise tak relevan (tipikal tabel enterprise)\nx_info = np.column_stack([\n    rng.lognormal(mean=2.0, sigma=1.4, size=n),  # Heavy-tail income\n    rng.normal(0, 1, size=n),\n    rng.uniform(-3, 3, size=n),\n    rng.exponential(scale=2.0, size=n),\n])\nx_noise = rng.normal(0, 1, size=(n, 20))\nX = np.hstack([x_info, x_noise])\n\n# Fungsi target non-smooth dengan ambang batas tajam (axis-aligned tabular)\nlogit = 2.2 * (x_info[:, 0] > 12.0) - 1.8 * (x_info[:, 1] > 0.4) + 1.5 * np.sin(2.5 * x_info[:, 2]) - 0.8 * (x_info[:, 3] > 3.5)\nprob = 1.0 / (1.0 + np.exp(-logit))\ny = (rng.uniform(0, 1, size=n) < prob).astype(int)\n\nX_tr, X_te, y_tr, y_te = train_test_split(X, y, test_size=0.25, stratify=y, random_state=42)\n\nmodels = {\n    \"MLP Mentah (Tanpa Preprocessing)\": MLPClassifier(hidden_layer_sizes=(32, 16), max_iter=120, random_state=42),\n    \"MLP + StandardScaler\": Pipeline([(\"sc\", StandardScaler()), (\"mlp\", MLPClassifier(hidden_layer_sizes=(32, 16), max_iter=120, random_state=42))]),\n    \"MLP + QuantileTransformer(normal)\": Pipeline([(\"qt\", QuantileTransformer(n_quantiles=200, output_distribution=\"normal\", random_state=42)), (\"mlp\", MLPClassifier(hidden_layer_sizes=(32, 16), max_iter=120, random_state=42))]),\n    \"HistGradientBoosting (Native)\": HistGradientBoostingClassifier(max_iter=60, max_depth=5, learning_rate=0.08, random_state=42),\n}\n\nfor name, clf in models.items():\n    clf.fit(X_tr, y_tr)\n    auc = roc_auc_score(y_te, clf.predict_proba(X_te)[:, 1])\n    print(f\"{name:35s} | Test ROC-AUC = {auc:.4f}\")",
