          "code": "import numpy as np\nfrom sklearn.ensemble import HistGradientBoostingClassifier\nfrom sklearn.metrics import roc_auc_score\nfrom sklearn.model_selection import train_test_split\nfrom sklearn.neural_network import MLPClassifier\nfrom sklearn.pipeline import Pipeline\nfrom sklearn.preprocessing import QuantileTransformer\n\n# Uji degradasi akurasi ketika jumlah fitur noise (uninformative features) ditambah dari 0 -> 40\nrng = np.random.default_rng(7)\nn = 900\nX_core = rng.normal(0, 1, size=(n, 4))\ny = (((X_core[:, 0] > 0.0) ^ (X_core[:, 1] > 0.0)) | (X_core[:, 2] > 1.1)).astype(int)\n\nprint(\"Noise Cols | HistGBDT AUC | Quantile-MLP AUC | Delta (GBDT - MLP)\")\nprint(\"-\" * 66)\nfor n_noise in [0, 10, 25, 40]:\n    X_full = np.hstack([X_core, rng.normal(0, 1, size=(n, n_noise))]) if n_noise > 0 else X_core\n    X_tr, X_te, y_tr, y_te = train_test_split(X_full, y, test_size=0.3, stratify=y, random_state=42)\n    gbdt = HistGradientBoostingClassifier(max_iter=50, max_depth=4, random_state=42).fit(X_tr, y_tr)\n    mlp = Pipeline([\n        (\"qt\", QuantileTransformer(n_quantiles=200, output_distribution=\"normal\", random_state=42)),\n        (\"m\", MLPClassifier(hidden_layer_sizes=(32, 16), max_iter=120, random_state=42)),\n    ]).fit(X_tr, y_tr)\n    auc_g = roc_auc_score(y_te, gbdt.predict_proba(X_te)[:, 1])\n    auc_m = roc_auc_score(y_te, mlp.predict_proba(X_te)[:, 1])\n    print(f\"{n_noise:10d} | {auc_g:12.4f} | {auc_m:16.4f} | {auc_g - auc_m:+18.4f}\")",
