          "id": "code-ml-17-4-ch17_4_sklearn",
          "title": "Scikit-Learn: Monotonic Constraint HistGBDT untuk Kredit Teregulasi",
          "language": "python",
          "filename": "17_4_monotonic_histgbdt_credit.py",
          "code": "import numpy as np\nfrom sklearn.ensemble import HistGradientBoostingClassifier\nfrom sklearn.metrics import roc_auc_score\nfrom sklearn.model_selection import train_test_split\n\n# Contoh Regulasi Risiko Kredit: Monotonic Constraint wajib (rasio utang naik -> risiko TIDAK BOLEH turun)\nrng = np.random.default_rng(42)\nn = 1500\ndebt_to_income = rng.uniform(0.05, 0.85, size=n)   # Fitur 0: harus monotonik NAIK (+1)\nincome_k = rng.lognormal(4.0, 0.45, size=n)        # Fitur 1: harus monotonik TURUN (-1)\ncredit_age = rng.uniform(1, 25, size=n)            # Fitur 2: bebas (0)\nX = np.column_stack([debt_to_income, income_k, credit_age])\n\nlogit = 4.2 * debt_to_income - 0.03 * income_k - 0.08 * credit_age - 0.4\ny = (rng.uniform(0, 1, size=n) < 1.0 / (1.0 + np.exp(-logit))).astype(int)\nX_tr, X_te, y_tr, y_te = train_test_split(X, y, test_size=0.25, stratify=y, random_state=42)\n\nunconstrained = HistGradientBoostingClassifier(max_iter=60, max_depth=5, random_state=42).fit(X_tr, y_tr)\nmonotonic_clf = HistGradientBoostingClassifier(\n    max_iter=60, max_depth=5, monotonic_cst=[1, -1, 0], random_state=42\n).fit(X_tr, y_tr)\n\n# Uji pelanggaran monotonisitas pada grid debt_to_income (fitur lain tetap)\ngrid = np.column_stack([np.linspace(0.1, 0.8, 50), np.full(50, 55.0), np.full(50, 8.0)])\nviol_free = int(np.sum(np.diff(unconstrained.predict_proba(grid)[:, 1]) < -1e-9))\nviol_mono = int(np.sum(np.diff(monotonic_clf.predict_proba(grid)[:, 1]) < -1e-9))\n\nprint(f\"Unconstrained HistGBDT | AUC={roc_auc_score(y_te, unconstrained.predict_proba(X_te)[:, 1]):.4f} | Pelanggaran Monotonik DTI={viol_free}\")\nprint(f\"Monotonic HistGBDT     | AUC={roc_auc_score(y_te, monotonic_clf.predict_proba(X_te)[:, 1]):.4f} | Pelanggaran Monotonik DTI={viol_mono}\")",
          "expectedOutput": "Unconstrained HistGBDT | AUC=0.8323 | Pelanggaran Monotonik DTI=11\nMonotonic HistGBDT     | AUC=0.8377 | Pelanggaran Monotonik DTI=0",
